SELECT trading_date,count(*),sum(net_amount) net,sum(net_amount) filter(where sales_nature='UNKNOWN') unknown FROM resolved_reporting_sales WHERE trading_date between '2026-10-26' and '2026-11-03' GROUP BY 1 ORDER BY 1;
SELECT s.trading_date,s.product_name_key,s.gross_amount,s.net_amount,s.authoritative_source,f.site_number,f.stock_code,f.product_name,f.raw_record_id,f.source_record_ref FROM resolved_reporting_sales s LEFT JOIN source_product_sale_fact f ON f.trading_date=s.trading_date AND regexp_replace(btrim(regexp_replace(lower(f.product_name),'[^a-z0-9]+',' ','g')),'^new ','')=s.product_name_key AND f.source_system=s.authoritative_source AND f.superseded_at IS NULL WHERE s.trading_date between '2026-11-02' and '2026-11-03' AND (s.sales_nature='UNKNOWN' OR s.net_amount IS NULL) ORDER BY s.net_amount DESC NULLS FIRST;
SELECT * FROM resolved_classified_wastage WHERE (wastage_date between '2026-11-02' and '2026-11-03' OR wastage_date IS NULL) AND (sales_nature='UNKNOWN' OR source_unit_cost IS NULL);
SELECT d.recipe_id,d.name,to_jsonb(d)-'id' recipe FROM canonical_recipe_definition d WHERE superseded_at IS NULL AND recipe_id IN(655,173);
